// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {VaultAdapter, Initializable} from "../src/VaultAdapter.sol";

contract InvMutTest is Test {
    VaultAdapter c;
    function setUp() public { c = new VaultAdapter(); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));

        // C's constructor disabled initializers, so EVERY initialize call must revert
        // with the Initializable.InvalidInitialization custom error (the initializer
        // guard rejects the call before any init logic runs). The mutant drops the
        // initializer modifier, so the revert instead surfaces as NotInitializing
        // from __Access_init's onlyInitializing check — different revert data.
        (bool ok, bytes memory ret) =
            address(c).call(abi.encodeWithSelector(VaultAdapter.initialize.selector, actor));

        assertFalse(ok, "initialize must revert on the initializer-disabled contract");
        assertTrue(
            ret.length == 4 &&
            bytes4(ret) == Initializable.InvalidInitialization.selector,
            "initialize must revert with InvalidInitialization"
        );
    }
}
